/**
 * Tournaments server action — the only writer for `tournaments`,
 * `tournamentPlayers`, and `tournamentMatches`.
 *
 * Trust model (see src/server/action-routes.ts): `tools.*` run RBAC-off,
 * so every operation below loads the tournament and checks the caller's
 * host role against the verified `userId` before writing. Direct client
 * writes are closed on all three collections for every role.
 *
 * Competitive integrity:
 * - Fixtures are generated by the pure functions in `../lib/tournaments.js`
 *   (deterministic circle method / seeded single-elimination bracket).
 * - A tournament match is an ordinary RallyCircle session scored through
 *   the existing scoreboard flow. A result counts only once it is
 *   genuinely finalized (`resultStatus() === 'final'`): winner set, not
 *   disputed, every recorded participant approved. `syncTournament`
 *   derives match winners from session scores; disputed results stay
 *   `scheduled` and never touch standings.
 * - Byes are free advances, never wins: bye matches carry no session and
 *   are excluded from standings.
 * - v1 tournaments are singles only (2-player matches).
 */

import type { ActionHandler, ActionResult, ActionTools } from 'deepspace/worker'
import type { Env } from '../../worker.js'
import { readMatchScore, resultStatus } from '../lib/rally-score.js'
import { validateSession, type RallySession } from '../lib/rally.js'
import {
  TOURNAMENT_MAX_PLAYERS,
  TOURNAMENT_MIN_PLAYERS,
  computeStandings,
  generateRoundRobin,
  generateSingleEliminationFirstRound,
  nextRoundPairings,
  singleEliminationRounds,
  sortPlayersBySeed,
  validateTournament,
  type StandingInput,
  type Tournament,
  type TournamentMatchInput,
  type TournamentMatchStatus,
  type TournamentPlayer,
} from '../lib/tournaments.js'

type Stored<T> = T & Record<string, unknown>

type TournamentResult<T = { recordId: string }> = ActionResult<T>

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function failure(error: string): TournamentResult {
  return { success: false, error }
}

function success(recordId: string): TournamentResult {
  return { success: true, data: { recordId } }
}

function paramString(params: Record<string, unknown>, key: string): string | null {
  const value = params[key]
  return typeof value === 'string' && value.length > 0 && value.length <= 200 ? value : null
}

function paramInt(params: Record<string, unknown>, key: string): number | null {
  const value = params[key]
  return typeof value === 'number' && Number.isInteger(value) ? value : null
}

interface RecordRow<T> {
  recordId: string
  createdAt: string
  data: T
}

function matchRecordId(tournamentId: string, round: number, slot: number): string {
  return `tm-${tournamentId.toLowerCase()}-r${round}s${slot}`
}

function parsePlayerIds(raw: unknown): string[] | null {
  if (typeof raw !== 'string') return null
  try {
    const parsed: unknown = JSON.parse(raw)
    if (!Array.isArray(parsed) || parsed.length < 1 || parsed.length > 2) return null
    if (!parsed.every(id => typeof id === 'string' && id.length > 0 && id.length <= 200)) return null
    return parsed as string[]
  } catch {
    return null
  }
}

async function loadTournament(tools: ActionTools, tournamentId: string): Promise<RecordRow<Tournament> | null> {
  const result = await tools.get<Stored<Tournament>>('tournaments', tournamentId)
  if (!result.success) return null
  const data = { ...result.data.record.data, status: result.data.record.data.status ?? 'created' }
  return { recordId: tournamentId, createdAt: result.data.record.createdAt, data }
}

async function listPlayers(tools: ActionTools, tournamentId: string): Promise<RecordRow<TournamentPlayer>[] | null> {
  const result = await tools.query<Stored<TournamentPlayer>>('tournamentPlayers', {
    where: { tournamentId },
    orderBy: 'seed',
    orderDir: 'asc',
    limit: TOURNAMENT_MAX_PLAYERS + 4,
  })
  if (!result.success) return null
  return result.data.records.map(record => ({
    recordId: record.recordId,
    createdAt: record.createdAt,
    data: { ...record.data, status: record.data.status ?? 'active' },
  }))
}

/**
 * List every match, round by round. Rounds are queried one at a time
 * (≤ 8 matches per round) so no single query can grow unbounded: a
 * 16-player round-robin has 120 matches across 15 rounds.
 */
async function listMatches(
  tools: ActionTools,
  tournamentId: string,
): Promise<RecordRow<TournamentMatchInput>[] | null> {
  const matches: RecordRow<TournamentMatchInput>[] = []
  for (let round = 1; round <= 16; round++) {
    const result = await tools.query<Stored<TournamentMatchInput>>('tournamentMatches', {
      where: { tournamentId, round },
      orderBy: 'slot',
      orderDir: 'asc',
      limit: 20,
    })
    if (!result.success) return null
    if (result.data.records.length === 0) break
    for (const record of result.data.records) {
      matches.push({
        recordId: record.recordId,
        createdAt: record.createdAt,
        data: {
          ...record.data,
          status: record.data.status ?? 'pending',
          sessionId: record.data.sessionId ?? '',
          winnerId: record.data.winnerId ?? '',
        },
      })
    }
  }
  return matches
}

/**
 * Bring 'scheduled' matches up to date from their sessions' scoreboards.
 * A match becomes 'final' only when its session result is genuinely
 * finalized. Disputed results stay 'scheduled' — the dispute must be
 * resolved through the normal review flow first. Returns the refreshed
 * match list.
 */
async function syncMatchResults(
  tools: ActionTools,
  tournamentId: string,
  matches: RecordRow<TournamentMatchInput>[],
): Promise<RecordRow<TournamentMatchInput>[]> {
  const refreshed = [...matches]
  for (let i = 0; i < refreshed.length; i++) {
    const match = refreshed[i]
    if (match.data.status !== 'scheduled' || !match.data.sessionId) continue
    const session = await tools.get<Stored<RallySession>>('sessions', match.data.sessionId)
    if (!session.success) continue
    const score = readMatchScore(session.data.record.data.matchScore)
    if (!score || resultStatus(score) !== 'final' || score.winner === null) continue
    const winnerTeam = score.teams[score.winner]
    const winnerId = winnerTeam[0]
    if (!winnerId) continue
    const updated = await tools.update('tournamentMatches', match.recordId, {
      status: 'final' as TournamentMatchStatus,
      winnerId,
    })
    if (updated.success) {
      refreshed[i] = { ...match, data: { ...match.data, status: 'final', winnerId } }
    }
  }
  return refreshed
}

/** Build standings inputs from finalized matches only. */
async function buildStandings(
  tools: ActionTools,
  playerIds: string[],
  matches: RecordRow<TournamentMatchInput>[],
): Promise<ReturnType<typeof computeStandings>> {
  const inputs: StandingInput[] = []
  for (const match of matches) {
    if (match.data.status !== 'final' || !match.data.sessionId) continue
    const playerIds = parsePlayerIds(match.data.playerIds)
    if (!playerIds || playerIds.length < 2) continue
    const session = await tools.get<Stored<RallySession>>('sessions', match.data.sessionId)
    if (!session.success) continue
    const score = readMatchScore(session.data.record.data.matchScore)
    if (!score || resultStatus(score) !== 'final' || score.winner === null) continue
    inputs.push({
      playerIds,
      status: 'final',
      winnerId: match.data.winnerId,
      result: { teams: score.teams, sets: score.sets, winnerId: match.data.winnerId },
    })
  }
  return computeStandings(playerIds, inputs)
}

async function createMatchRow(
  tools: ActionTools,
  tournamentId: string,
  round: number,
  slot: number,
  playerIds: string[],
  status: TournamentMatchStatus,
  winnerId: string,
): Promise<boolean> {
  const recordId = matchRecordId(tournamentId, round, slot)
  const created = await tools.create(
    'tournamentMatches',
    {
      tournamentId,
      round,
      slot,
      playerIds: JSON.stringify(playerIds),
      sessionId: '',
      status,
      winnerId,
    },
    recordId,
  )
  if (created.success) return true
  // A retry of the same generation hits the deterministic record id;
  // treat the duplicate as the already-created row.
  const existing = await tools.get<Stored<TournamentMatchInput>>('tournamentMatches', recordId)
  return existing.success
}

export const tournamentAction: ActionHandler<Env> = async ({ userId, params, tools }) => {
  if (!isRecord(params) || typeof params.operation !== 'string') {
    return failure('Invalid tournament request.')
  }
  const operation = params.operation

  if (operation === 'createTournament') {
    const error = validateTournament(params)
    if (error) return failure(error)
    const created = await tools.create('tournaments', {
      name: (params.name as string).trim(),
      format: params.format,
      status: 'created',
      maxPlayers: typeof params.maxPlayers === 'number' ? params.maxPlayers : TOURNAMENT_MAX_PLAYERS,
    })
    if (!created.success) return failure('The tournament could not be created.')
    return success(created.data.recordId)
  }

  const tournamentId = paramString(params, 'tournamentId')
  if (!tournamentId) return failure('Invalid tournament request.')
  const tournament = await loadTournament(tools, tournamentId)
  if (!tournament) return failure('This tournament is unavailable.')
  const isHost = tournament.data.hostId === userId

  if (operation === 'getTournament' || operation === 'getStandings') {
    const [players, matches] = await Promise.all([
      listPlayers(tools, tournamentId),
      listMatches(tools, tournamentId),
    ])
    if (!players || !matches) return failure('This tournament could not be loaded.')
    const activePlayers = players.filter(player => player.data.status === 'active')
    const playerIds = sortPlayersBySeed(activePlayers.map(player => player.data)).map(player => player.userId)
    const standings = await buildStandings(tools, playerIds, matches)
    if (operation === 'getStandings') {
      return {
        success: true,
        data: { tournamentId, standings },
      } as TournamentResult<{ tournamentId: string; standings: unknown[] }>
    }
    return {
      success: true,
      data: {
        recordId: tournamentId,
        tournament: tournament.data,
        players: players.map(player => ({
          recordId: player.recordId,
          userId: player.data.userId,
          seed: player.data.seed,
          status: player.data.status,
        })),
        matches: matches.map(match => ({
          recordId: match.recordId,
          round: match.data.round,
          slot: match.data.slot,
          playerIds: parsePlayerIds(match.data.playerIds) ?? [],
          sessionId: match.data.sessionId,
          status: match.data.status,
          winnerId: match.data.winnerId,
        })),
        standings,
      },
    } as TournamentResult<{ recordId: string; tournament: Tournament; players: unknown[]; matches: unknown[]; standings: unknown[] }>
  }

  if (!isHost) return failure('Only the tournament host can manage it.')

  if (operation === 'addPlayer') {
    if (tournament.data.status !== 'created') return failure('Players can only be added before the tournament starts.')
    const targetUserId = paramString(params, 'userId')
    if (!targetUserId) return failure('Invalid tournament request.')
    const players = await listPlayers(tools, tournamentId)
    if (!players) return failure('Players could not be loaded.')
    const existing = players.find(player => player.data.userId === targetUserId)
    if (existing) {
      if (existing.data.status === 'active') return success(existing.recordId)
      const restored = await tools.update('tournamentPlayers', existing.recordId, { status: 'active' })
      return restored.success ? success(existing.recordId) : failure('That player could not be added.')
    }
    const activeCount = players.filter(player => player.data.status === 'active').length
    if (activeCount >= tournament.data.maxPlayers) return failure('This tournament is full.')
    const created = await tools.create('tournamentPlayers', {
      tournamentId,
      userId: targetUserId,
      seed: activeCount + 1,
      status: 'active',
    })
    if (!created.success) return failure('That player could not be added.')
    return success(created.data.recordId)
  }

  if (operation === 'removePlayer') {
    if (tournament.data.status !== 'created') return failure('Players can only be removed before the tournament starts.')
    const targetUserId = paramString(params, 'userId')
    if (!targetUserId) return failure('Invalid tournament request.')
    const players = await listPlayers(tools, tournamentId)
    if (!players) return failure('Players could not be loaded.')
    const existing = players.find(player => player.data.userId === targetUserId)
    if (!existing) return success(tournamentId)
    const removed = await tools.remove('tournamentPlayers', existing.recordId)
    return removed.success ? success(tournamentId) : failure('That player could not be removed.')
  }

  if (operation === 'startTournament') {
    if (tournament.data.status !== 'created') return failure('This tournament has already started.')
    const players = await listPlayers(tools, tournamentId)
    if (!players) return failure('Players could not be loaded.')
    const active = sortPlayersBySeed(players.filter(player => player.data.status === 'active').map(player => player.data))
    if (active.length < TOURNAMENT_MIN_PLAYERS) {
      return failure(`Add at least ${TOURNAMENT_MIN_PLAYERS} players before starting.`)
    }
    const playerIds = active.map(player => player.userId)
    let created = 0
    if (tournament.data.format === 'round-robin') {
      for (const fixture of generateRoundRobin(playerIds)) {
        if (await createMatchRow(tools, tournamentId, fixture.round, fixture.slot, fixture.players, 'pending', '')) created++
      }
    } else {
      for (const match of generateSingleEliminationFirstRound(playerIds)) {
        if (match.bye) {
          if (await createMatchRow(tools, tournamentId, match.round, match.slot, match.players, 'final', match.players[0])) created++
        } else if (await createMatchRow(tools, tournamentId, match.round, match.slot, match.players, 'pending', '')) {
          created++
        }
      }
    }
    if (created === 0) return failure('Fixtures could not be created.')
    const updated = await tools.update('tournaments', tournamentId, { status: 'in_progress' })
    return updated.success ? success(tournamentId) : failure('The tournament could not be started.')
  }

  if (operation === 'scheduleMatch') {
    if (tournament.data.status !== 'in_progress') return failure('Matches can only be scheduled while the tournament is in progress.')
    const round = paramInt(params, 'round')
    const slot = paramInt(params, 'slot')
    if (round === null || slot === null || round < 1 || slot < 0) return failure('Invalid tournament request.')
    const matches = await listMatches(tools, tournamentId)
    if (!matches) return failure('Matches could not be loaded.')
    const match = matches.find(m => m.data.round === round && m.data.slot === slot)
    if (!match) return failure('That match does not exist.')
    if (match.data.status === 'scheduled' && match.data.sessionId) return success(match.data.sessionId)
    if (match.data.status !== 'pending') return failure('That match cannot be scheduled.')
    if (
      typeof params.court !== 'string' ||
      typeof params.location !== 'string' ||
      typeof params.startsAt !== 'string' ||
      typeof params.durationMinutes !== 'number'
    ) {
      return failure('Invalid match session.')
    }
    const playerIds = parsePlayerIds(match.data.playerIds)
    if (!playerIds || playerIds.length !== 2) return failure('That match has no opponent yet.')
    const sessionError = validateSession(
      {
        format: 'Singles',
        title: `${tournament.data.name} — Round ${round}`,
        court: params.court,
        location: params.location,
        startsAt: params.startsAt,
        durationMinutes: params.durationMinutes,
        targetPlayers: 2,
        capacity: 2,
        level: 'All levels',
        notes: '',
      },
      Date.now(),
    )
    if (sessionError) return failure(sessionError)
    const created = await tools.create('sessions', {
      format: 'Singles',
      title: `${tournament.data.name} — Round ${round}`,
      court: (params.court as string).trim(),
      location: (params.location as string).trim(),
      startsAt: params.startsAt,
      durationMinutes: params.durationMinutes,
      targetPlayers: 2,
      capacity: 2,
      level: 'All levels',
      notes: '',
      chatChannelId: '',
      status: 'open',
    })
    if (!created.success) return failure('The match session could not be created.')
    const updated = await tools.update('tournamentMatches', match.recordId, {
      sessionId: created.data.recordId,
      status: 'scheduled' as TournamentMatchStatus,
    })
    if (!updated.success) return failure('The match could not be linked to its session.')
    return success(created.data.recordId)
  }

  if (operation === 'advanceRound') {
    if (tournament.data.status !== 'in_progress') return failure('Only a tournament in progress can advance.')
    if (tournament.data.format !== 'single-elimination') {
      return failure('Only single-elimination tournaments advance round by round.')
    }
    const round = paramInt(params, 'round')
    if (round === null || round < 1) return failure('Invalid tournament request.')
    const players = await listPlayers(tools, tournamentId)
    if (!players) return failure('Players could not be loaded.')
    const activeCount = players.filter(player => player.data.status === 'active').length
    const totalRounds = singleEliminationRounds(activeCount)
    if (round >= totalRounds) return failure('This is the final round. Sync the tournament to complete it.')
    const matches = await listMatches(tools, tournamentId)
    if (!matches) return failure('Matches could not be loaded.')
    const synced = await syncMatchResults(tools, tournamentId, matches)
    const roundMatches = synced.filter(m => m.data.round === round)
    if (roundMatches.length === 0) return failure('That round does not exist.')
    if (roundMatches.some(m => m.data.status !== 'final')) {
      return failure('Every match in this round must be final before advancing.')
    }
    const existingNext = synced.filter(m => m.data.round === round + 1)
    if (existingNext.length > 0) return success(tournamentId)
    let pairings
    try {
      pairings = nextRoundPairings(roundMatches.map(m => ({ slot: m.data.slot, winnerId: m.data.winnerId })))
    } catch {
      return failure('This round cannot be advanced yet.')
    }
    for (const pairing of pairings) {
      if (!(await createMatchRow(tools, tournamentId, round + 1, pairing.slot, pairing.players, 'pending', ''))) {
        return failure('The next round could not be created.')
      }
    }
    return success(tournamentId)
  }

  if (operation === 'syncTournament') {
    if (tournament.data.status !== 'in_progress') return failure('Only a tournament in progress can be synced.')
    const players = await listPlayers(tools, tournamentId)
    if (!players) return failure('Players could not be loaded.')
    const activeCount = players.filter(player => player.data.status === 'active').length
    const matches = await listMatches(tools, tournamentId)
    if (!matches) return failure('Matches could not be loaded.')
    const synced = await syncMatchResults(tools, tournamentId, matches)
    const played = synced.filter(m => {
      const playerIds = parsePlayerIds(m.data.playerIds)
      return playerIds !== null && playerIds.length === 2
    })
    // Completion needs the full fixture count, not just "everything that
    // exists so far is final": in single elimination the next round does
    // not exist until advanceRound creates it, so counting only existing
    // matches would complete the tournament after round 1.
    const expectedPlayed =
      tournament.data.format === 'round-robin'
        ? (activeCount * (activeCount - 1)) / 2
        : activeCount - 1
    const allFinal = played.length === expectedPlayed && played.every(m => m.data.status === 'final')
    if (allFinal) {
      const updated = await tools.update('tournaments', tournamentId, { status: 'completed' })
      if (!updated.success) return failure('The tournament could not be completed.')
      return {
        success: true,
        data: { recordId: tournamentId, status: 'completed', finalized: played.length },
      } as TournamentResult<{ recordId: string; status: string; finalized: number }>
    }
    return {
      success: true,
      data: {
        recordId: tournamentId,
        status: 'in_progress',
        finalized: played.filter(m => m.data.status === 'final').length,
      },
    } as TournamentResult<{ recordId: string; status: string; finalized: number }>
  }

  if (operation === 'cancelTournament') {
    if (tournament.data.status === 'completed') return failure('A completed tournament cannot be cancelled.')
    if (tournament.data.status === 'cancelled') return success(tournamentId)
    const matches = await listMatches(tools, tournamentId)
    if (!matches) return failure('Matches could not be loaded.')
    for (const match of matches) {
      if (match.data.status === 'pending' || match.data.status === 'scheduled') {
        await tools.update('tournamentMatches', match.recordId, { status: 'cancelled' as TournamentMatchStatus })
        if (match.data.sessionId) {
          await tools.update('sessions', match.data.sessionId, { status: 'cancelled' })
        }
      }
    }
    const updated = await tools.update('tournaments', tournamentId, { status: 'cancelled' })
    return updated.success ? success(tournamentId) : failure('The tournament could not be cancelled.')
  }

  return failure('Invalid tournament request.')
}
